let _markdown = "\n\nUsage [#usage]\n\n<FeedbackBlock id=\"dcfc5254cade2422\" body=\"Thanks to the Twoslash integration of Shiki, the default code syntax highlighter, it is as simple as adding a transformer.\">\n  Thanks to the Twoslash integration of [Shiki](https://github.com/shikijs/shiki), the default code syntax highlighter, it is as simple as adding a transformer.\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"npm\" groupId=\"package-manager\" persist>\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"npm\">\n      npm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"pnpm\">\n      pnpm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"yarn\">\n      yarn\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"bun\">\n      bun\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"npm\">\n    ```bash\n    npm install fumadocs-twoslash twoslash\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"pnpm\">\n    ```bash\n    pnpm add fumadocs-twoslash twoslash\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"yarn\">\n    ```bash\n    yarn add fumadocs-twoslash twoslash\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"bun\">\n    ```bash\n    bun add fumadocs-twoslash twoslash\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock id=\"9821cb941800daaa\" body=\"For Next.js, you need to externalize the following deps:\">\n  For Next.js, you need to externalize the following deps:\n</FeedbackBlock>\n\n```js title=\"next.config.mjs (Next.js)\"\nconst config = {\n  reactStrictMode: true,\n  // [!code ++]\n  serverExternalPackages: ['typescript', 'twoslash'],\n};\n```\n\n<FeedbackBlock id=\"8b3ce1310bcaf358\" body=\"Add to your Shiki transformers.\">\n  Add to your Shiki transformers.\n</FeedbackBlock>\n\n```ts title=\"source.config.ts (Fumadocs MDX)\"\nimport { defineConfig } from 'fumadocs-mdx/config';\nimport { transformerTwoslash } from 'fumadocs-twoslash';\nimport { rehypeCodeDefaultOptions } from 'fumadocs-core/mdx-plugins';\n\nexport default defineConfig({\n  mdxOptions: {\n    rehypeCodeOptions: {\n      themes: {\n        light: 'github-light',\n        dark: 'github-dark',\n      },\n      transformers: [...(rehypeCodeDefaultOptions.transformers ?? []), transformerTwoslash()],\n\n      // important: Shiki doesn't support lazy loading languages for codeblocks in Twoslash popups\n      // make sure to define them first (e.g. the common ones)\n      langs: ['js', 'jsx', 'ts', 'tsx'],\n    },\n  },\n});\n```\n\n<FeedbackBlock id=\"fe57a7a139a6a9d6\" body=\"Add styles, Tailwind CSS v4 is required.\">\n  Add styles, Tailwind CSS v4 is required.\n</FeedbackBlock>\n\n```css title=\"Tailwind CSS\"\n@import 'fumadocs-twoslash/twoslash.css';\n```\n\n<FeedbackBlock id=\"bda05426503bbb4a\" body=\"Add MDX components.\">\n  Add MDX components.\n</FeedbackBlock>\n\n```tsx title=\"mdx-components.tsx\"\nimport * as Twoslash from 'fumadocs-twoslash/ui';\nimport defaultComponents from 'fumadocs-ui/mdx';\nimport type { MDXComponents } from 'mdx/types';\n\nexport function getMDXComponents(components?: MDXComponents): MDXComponents {\n  return {\n    ...defaultComponents,\n    // [!code ++]\n    ...Twoslash,\n    ...components,\n  };\n}\n```\n\n<FeedbackBlock id=\"74730ce8446f666c\" body=\"Now you can add twoslash meta string to codeblocks.\">\n  Now you can add `twoslash` meta string to codeblocks.\n</FeedbackBlock>\n\n````md\n```ts twoslash\nconsole.log('Hello World');\n```\n````\n\nCache [#cache]\n\n<FeedbackBlock id=\"f4915a119ce14686\" body=\"Optionally, you can enable filesystem cache with typesCache option:\">\n  Optionally, you can enable filesystem cache with `typesCache` option:\n</FeedbackBlock>\n\n```ts twoslash title=\"source.config.ts\"\nimport { transformerTwoslash } from 'fumadocs-twoslash';\nimport { createFileSystemTypesCache } from 'fumadocs-twoslash/cache-fs';\n\ntransformerTwoslash({\n  typesCache: createFileSystemTypesCache(),\n});\n```\n\nExample [#example]\n\n<FeedbackBlock id=\"81cb7d5065e0c53e\" body=\"Learn more about Twoslash notations.\">\n  Learn more about [Twoslash notations](https://twoslash.netlify.app/refs/notations).\n</FeedbackBlock>\n\n```ts twoslash title=\"Test\" lineNumbers\ntype Player = {\n  /**\n   * The player name\n   * @default 'user'\n   */\n  name: string;\n};\n\n// ---cut---\n// @noErrors\nconsole.g;\n//       ^|\n\nconst player: Player = { name: 'Hello World' };\n//    ^?\n```\n\n```ts twoslash\nconst a = '123';\n\nconsole.log(a);\n//      ^^^\n```\n\n```ts twoslash\n// @errors: 2588\nconst a = '123';\n\na = 132;\n```\n";
